"""V9: case study after the pipeline page intro, translated together with its media."""
import re,html
LANGS=['fr','en','pt-BR','es']
def apply(root,catalog):
 def T(fr,en,pt,es):catalog[fr]=dict(zip(LANGS[1:],[en,pt,es]));return html.escape(fr)
 title=T('Déclarations de chantier : transformer des échanges dispersés en actions suivies','Work declarations: turn scattered exchanges into tracked actions','Declarações de obras: transformar informações dispersas em ações acompanhadas','Declaraciones de obra: transformar intercambios dispersos en acciones seguidas')
 context=T('Avant des travaux à proximité de réseaux, les déclarations de chantier permettent de recueillir les informations nécessaires auprès des exploitants concernés. Leur suivi implique de réunir des déclarations, des réponses, des plans et des échéances.','Before work near utility networks, work declarations help obtain the necessary information from the relevant network operators. Tracking them involves bringing together declarations, responses, plans and deadlines.','Antes de obras próximas a redes, as declarações permitem reunir as informações necessárias junto aos operadores envolvidos. Seu acompanhamento exige reunir declarações, respostas, plantas e prazos.','Antes de realizar obras cerca de redes, las declaraciones permiten reunir la información necesaria de los operadores implicados. Su seguimiento exige reunir declaraciones, respuestas, planos y plazos.')
 label=T('Exemple fictif illustrant un processus de suivi autour de PROTYS','Fictional example illustrating a tracking process around PROTYS','Exemplo fictício de um processo de acompanhamento com o PROTYS','Ejemplo ficticio de un proceso de seguimiento con PROTYS')
 lead=T('À chaque étape, le dossier gagne en contexte.','At each stage, the case gains context.','A cada etapa, o dossiê ganha contexto.','En cada etapa, el expediente gana contexto.')
 explanation=T('Les déclarations sont rattachées au bon chantier, complétées par les informations internes, puis rapprochées des réponses et des documents reçus. Le bilan permet de préparer les actions du robot. Leurs résultats reviennent ensuite enrichir le suivi, y compris lorsqu’une réponse manque ou qu’une tâche doit être reprise.','Declarations are linked to the right worksite, enriched with internal information, then matched with responses and documents received. The overview prepares the robot’s actions. Their results then feed back into tracking, including pending responses and tasks that need retrying.','As declarações são vinculadas à obra correta, complementadas por informações internas e cruzadas com as respostas e os documentos recebidos. O balanço prepara as ações do robô. Os resultados voltam a enriquecer o acompanhamento, inclusive quando falta uma resposta ou uma tarefa precisa ser repetida.','Las declaraciones se vinculan a la obra correcta, se completan con información interna y se cruzan con las respuestas y los documentos recibidos. El balance permite preparar las acciones del robot. Sus resultados enriquecen el seguimiento, incluso si falta una respuesta o debe repetirse una tarea.')
 transition=T('Ce principe peut s’appliquer à d’autres processus et à vos applications existantes.','This principle can apply to other processes and your existing applications.','Esse princípio pode ser aplicado a outros processos e às suas aplicações existentes.','Este principio puede aplicarse a otros procesos y a sus aplicaciones existentes.')
 transcript=T('Lire les étapes du suivi de chantier','Read the worksite tracking steps','Ler as etapas do acompanhamento da obra','Leer las etapas del seguimiento de obra')
 steps=[T('Collecter les déclarations, réponses, plans et informations internes.','Collect declarations, responses, plans and internal information.','Coletar declarações, respostas, plantas e informações internas.','Recopilar declaraciones, respuestas, planos e información interna.'),T('Harmoniser les données et les rattacher au chantier, à sa localisation et à l’équipe concernée.','Harmonise data and link it to the worksite, its location and the responsible team.','Harmonizar os dados e vinculá-los à obra, à localização e à equipe responsável.','Armonizar los datos y vincularlos a la obra, su ubicación y el equipo responsable.'),T('Enrichir le bilan avec les exploitants attendus, les réponses reçues, les pièces, les délais et l’historique.','Enrich the overview with expected operators, responses received, documents, elapsed time and history.','Enriquecer o balanço com operadores esperados, respostas recebidas, documentos, prazos e histórico.','Enriquecer el balance con operadores esperados, respuestas recibidas, documentos, plazos e historial.'),T('Préparer les tâches de relance, de récupération des documents et de dépôt en gestion documentaire.','Prepare reminder, document retrieval and document management upload tasks.','Preparar tarefas de cobrança de respostas, recuperação e arquivamento de documentos.','Preparar tareas de recordatorio, recuperación y archivo de documentos.'),T('Faire exécuter les tâches par le robot et réintégrer leurs résultats dans le suivi.','Have the robot execute tasks and feed their results back into tracking.','Executar as tarefas com o robô e reintegrar os resultados ao acompanhamento.','Ejecutar las tareas con el robot y reintegrar los resultados al seguimiento.'),T('Restituer les documents et le bilan aux équipes ; conserver visibles une réponse attendue et un dépôt à reprendre.','Deliver documents and the overview to the teams; keep a pending response and an upload to retry visible.','Disponibilizar documentos e balanço às equipes; manter visíveis uma resposta pendente e um envio a repetir.','Entregar documentos y balance a los equipos; mantener visibles una respuesta pendiente y una carga por reintentar.')]
 other=T('Découvrir un autre exemple : la planification d’une demande','Discover another example: scheduling a request','Descobrir outro exemplo: planejar uma solicitação','Descubrir otro ejemplo: planificar una solicitud')
 block=f'''<section id="chantier-protys" aria-labelledby="protys-title"><h2 id="protys-title">{title}</h2><p>{context}</p>
<figure class="pipeline-demo" data-media-base="assets/protys/protys" aria-describedby="pipeline-demo-caption">
<div class="pipeline-media protys-media"><img class="pipeline-poster" src="assets/protys/protys-fr.webp" alt="" width="1320" height="800"/><video id="pipeline-animation" muted loop playsinline preload="none" poster="assets/protys/protys-fr.webp" width="1320" height="800" aria-hidden="true" tabindex="-1"></video></div>
<figcaption id="pipeline-demo-caption">{label}</figcaption><div class="actions pipeline-controls"><button class="pipeline-toggle" type="button" aria-controls="pipeline-animation" data-msg="pipeline.play" hidden>Lire l’animation</button><a class="pipeline-expand text-link" href="assets/protys/protys-fr.webp" data-msg="pipeline.expand">Agrandir le schéma</a></div></figure>
<p><strong>{lead}</strong> {explanation}</p><details><summary>{transcript}</summary><ol>{''.join('<li>'+s+'</li>' for s in steps)}</ol></details><p>{transition}</p>
<dialog id="pipeline-dialog" data-kind="protys" aria-labelledby="pipeline-dialog-title"><div class="pipeline-dialog-header"><h2 id="pipeline-dialog-title" data-msg="pipeline.dialog">Vue agrandie du pipeline CLN</h2><button type="button" data-msg="pipeline.close">Fermer</button></div><div class="pipeline-zoom-scroll" tabindex="0"><img src="assets/protys/protys-fr.webp" alt="" width="1320" height="800"/></div></dialog></section>'''
 p=root/'pipelines.html';s=p.read_text()
 s=re.sub(r'<section id="chantier-protys"[^>]*>.*?</section>','',s,flags=re.S)
 # Generator normally rewrites the original example; unwrap defensively for idempotence.
 s=re.sub(r'(<section id="exemple">)\s*<details class="pipeline-other-example"><summary>.*?</summary>(.*?)</details>\s*</section>',r'\1\2</section>',s,flags=re.S)
 match=re.search(r'<section id="exemple">(.*?)</section>',s,flags=re.S)
 if not match:raise ValueError('Missing original planning example')
 old='<section id="exemple"><details class="pipeline-other-example"><summary>'+other+'</summary>'+match[1]+'</details></section>'
 s=s[:match.start()]+old+s[match.end():]
 start=s.index('<main id="main-content">');end=s.index('</section>',start)+len('</section>');s=s[:end]+'\n'+block+s[end:]
 s=re.sub(r'<script defer src="pipeline-animation.js[^\"]*">\s*</script>\s*','',s)
 s=s.replace('</head>','<script defer src="pipeline-animation.js?v=20261029-v9"></script>\n</head>');p.write_text(s)
 for name in ['index','solutions','pipelines','approche','realisations','diagnostic','contact','merci','mentions-legales','confidentialite']:
  p=root/(name+'.html');p.write_text(re.sub(r'\?v=20261029-v[6789]','?v=20261029-v9',p.read_text()))
